) AS source (ExamYear, Subject, Lesson, Topic, SourceRow, QuestionText, OptionA, OptionB, OptionC, OptionD, CorrectOption, Explanation)
ON target.ExamYear = source.ExamYear AND target.SourceRow = source.SourceRow
WHEN MATCHED THEN UPDATE SET
    Subject = source.Subject, Lesson = source.Lesson, Topic = source.Topic, QuestionText = source.QuestionText,
    OptionA = source.OptionA, OptionB = source.OptionB, OptionC = source.OptionC, OptionD = source.OptionD,
    CorrectOption = source.CorrectOption, Explanation = source.Explanation, IsActive = 1, UpdatedAt = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT
    (ExamYear, Subject, Lesson, Topic, SourceRow, QuestionText, OptionA, OptionB, OptionC, OptionD, CorrectOption, Explanation)
    VALUES (source.ExamYear, source.Subject, source.Lesson, source.Topic, source.SourceRow, source.QuestionText,
            source.OptionA, source.OptionB, source.OptionC, source.OptionD, source.CorrectOption, source.Explanation);
COMMIT TRANSACTION;
GO

